BEGIN TRANSACTION;
CREATE TABLE scenarios (
	scenario_id VARCHAR NOT NULL, 
	scenario_json TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (scenario_id)
);
INSERT INTO "scenarios" VALUES('demo-smartwings-123','{"scenario_id": "demo-smartwings-123", "client_profile": {"name": "SmartWings", "size": "Enterprise (Airline)", "budget_cycle": "Q4", "decision_timeline": "3 months", "buyer_persona": "CIO or VP of Customer Experience, focused on operational efficiency and passenger satisfaction"}, "value_proposition": "Ciklum provides a full-cycle passenger activity tracking system driven by AI. It manages interactions from initial ticket purchase to cancellations, claims, and missing luggage. Users can make requests via text, document, or bot calls with clear communication at every step. Post-cycle, AI agents generate metrics and survey results. This radically reduces agent handling time and improves CSAT through predictive analytics.", "buying_constraints": ["Integrating with legacy flight booking systems", "Ensuring compliance with aviation data regulations", "Proving ROI against existing customer support costs"], "objections": [{"id": "1", "title": "Integration Risk", "detail": "How do we know your AI system can safely integrate with our legacy PSS without causing downtime?", "tested": false}, {"id": "2", "title": "Accuracy of AI Claims", "detail": "Handling missing luggage and claims via AI sounds risky. What happens if the AI makes a mistake and approves a fraudulent claim?", "tested": false}, {"id": "3", "title": "Cost vs Loyalty", "detail": "We already have a massive call center. Will replacing parts of it with AI actually improve passenger loyalty, or just cut costs and frustrate users?", "tested": false}, {"id": "4", "title": "Training Reality", "detail": "We don\u2019t have a team of prompt engineers or AI scientists. How much effort is required from our internal team to train and maintain these models?", "tested": false}, {"id": "5", "title": "Data Privacy", "detail": "Our passengers trust us with sensitive PII like passport details and payment info. How does your AI ensure this data isn''t exposed or used to train public models?", "tested": false}]}','2026-03-09 15:35:11.723613');
CREATE TABLE "session_scores" (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        session_id VARCHAR,
                        project_id VARCHAR,
                        overall_score INTEGER,
                        objection_handling INTEGER,
                        communication_clarity INTEGER,
                        weaknesses_json TEXT,
                        created_at DATETIME
                    );
INSERT INTO "session_scores" VALUES(1,'8721fcfe-bd1f-484b-823d-1e788c65bf20','scenario_techcorp_da4e80e8',65,40,80,'["Insufficient evidence to address satisfaction with current vendor", "Limited handling of budget constraints", "Vague mention of integration without specific examples"]','2026-03-05 17:02:24.321159');
INSERT INTO "session_scores" VALUES(2,'8ffb8507-9ceb-47da-8d44-145bb51234ad','scenario_techcorp_da4e80e8',63,40,80,'["Limited addressing of specific pain points", "Lack of strong proof points", "Insufficient handling of objections"]','2026-03-05 17:05:19.883114');
INSERT INTO "session_scores" VALUES(3,'seed-session-sw-001','demo-smartwings-123',48,30,62,'["No specific ROI numbers or case study references \u2014 vague ''cost savings'' claim destroyed credibility", "Completely deflected the Sabre integration question without any concrete answer", "Did not address data privacy concerns at all despite the buyer explicitly raising them"]','2026-03-03 15:46:43.802299');
INSERT INTO "session_scores" VALUES(4,'seed-session-sw-002','demo-smartwings-123',67,62,76,'["Data privacy answer was thin \u2014 said ''dedicated tenant'' and ''GDPR'' but gave no certifications, hosting specifics, or breach protocols", "Close was too passive \u2014 proposed a call in ''two weeks'' without locking a specific date or owner", "Conciseness dipped in the ROI section \u2014 the calculation was strong but could have been tighter"]','2026-03-07 15:46:43.808069');
CREATE TABLE "sessions" (
                        id VARCHAR PRIMARY KEY,
                        project_id VARCHAR,
                        scenario_id VARCHAR,
                        transcript_json TEXT,
                        created_at DATETIME
                    );
INSERT INTO "sessions" VALUES('8721fcfe-bd1f-484b-823d-1e788c65bf20','scenario_techcorp_da4e80e8','scenario_techcorp_da4e80e8','[{"role": "buyer", "content": "Thanks for making the time. I''ll be honest \u2014 we''ve been burned by vendors before, so I need to see real proof before I bring anything to the board."}, {"role": "seller", "content": "Absolutely, I appreciate the candor. That''s actually one of the reasons I wanted to start with a case study from a company very similar to yours in the manufacturing space."}, {"role": "buyer", "content": "Fine, but let''s cut to the chase \u2014 what''s this going to cost us? We''re in the middle of a cost-reduction initiative."}, {"role": "seller", "content": "Hi there, I''m here to talk about TechCorp''s cloud security. I understand you''re looking to reduce data breach risks. how do you currently handle your cloud security posture?"}, {"role": "buyer", "content": "We''re currently satisfied with our existing security provider and don''t see a pressing need to switch at this time. What can you offer that would make us consider changing?"}, {"role": "seller", "content": "I understand that security is a top priority and doing it internally seems safer. However, TechCorp''s solution actually reduces the risk of internal breach and can save you millions in potential data breach costs. We can start with a pilot to minimize your budget impact."}, {"role": "seller", "content": "Our solution is designed to work with your existing providers, not necessarily replace them entirely on day one. We can fill the gaps they miss, especially in cloud-native security where traditional vendors often lag. This prevents vendor lock-in and gives you a more robust defense-in-depth strategy."}]','2026-03-05 17:02:24.314263');
INSERT INTO "sessions" VALUES('8ffb8507-9ceb-47da-8d44-145bb51234ad','scenario_techcorp_da4e80e8','scenario_techcorp_da4e80e8','[{"role": "buyer", "content": "Thanks for making the time. I''ll be honest \u2014 we''ve been burned by vendors before, so I need to see real proof before I bring anything to the board."}, {"role": "seller", "content": "Absolutely, I appreciate the candor. That''s actually one of the reasons I wanted to start with a case study from a company very similar to yours in the manufacturing space."}, {"role": "buyer", "content": "Fine, but let''s cut to the chase \u2014 what''s this going to cost us? We''re in the middle of a cost-reduction initiative."}]','2026-03-05 17:05:19.875617');
INSERT INTO "sessions" VALUES('seed-session-sw-001','demo-smartwings-123','demo-smartwings-123','[{"role": "seller", "content": "Hi, thank you for taking the time to meet with me today. I''m here from Ciklum and we have a really exciting AI solution that can help airlines like SmartWings. Basically, it''s a passenger tracking system that uses artificial intelligence to handle lots of different customer interactions automatically. It''s quite innovative and we''ve had a lot of interest from airlines recently."}, {"role": "buyer", "content": "That sounds pretty generic. Every vendor claims their AI is innovative. What specifically does your system do that we can''t already do with our current customer support tools?"}, {"role": "seller", "content": "Right, great question. So our system covers the full passenger journey \u2014 it handles things like booking inquiries, cancellations, claims, luggage issues. It uses AI to automate the responses and route them appropriately. It''s very comprehensive. We''ve worked with a number of clients and they generally see cost savings and improved customer satisfaction."}, {"role": "buyer", "content": "What does ''generally see cost savings'' actually mean? Can you give me a number? And how would this integrate with our Sabre PSS? We can''t have anything that risks touching our flight operations systems."}, {"role": "seller", "content": "In terms of numbers, it kind of depends on the implementation and the scope of what you roll out. Some clients save quite a bit, others less so. It really varies. Regarding Sabre integration \u2014 yes, we do work with legacy systems. Our team is experienced with integrations. We''d need to look at your specific setup of course, but generally speaking we have done this kind of thing before. It usually goes fine."}, {"role": "buyer", "content": "''Usually goes fine'' is not very reassuring when we''re talking about a system connected to flight operations. What''s your actual track record with Sabre? And what happens if something goes wrong mid-integration?"}, {"role": "seller", "content": "I understand your concern. We take integration very seriously and have a thorough testing process. We would work closely with your IT team and have rollback procedures in place. I''d need to connect you with our technical team to go into the specifics. I think the important thing is that our AI solution overall is really well designed and your passengers would really see the difference in their experience. Would you be interested in setting up a demo with the technical team?"}, {"role": "buyer", "content": "Maybe. But I''m still not clear on the ROI, the integration risks, or how you handle our passengers'' PII data. I need those answers before we go further."}]','2026-03-03 15:46:43.802299');
INSERT INTO "sessions" VALUES('seed-session-sw-002','demo-smartwings-123','demo-smartwings-123','[{"role": "seller", "content": "Good morning. I appreciate your time. I''ll be direct \u2014 Ciklum''s AI passenger activity system delivers, on average, a 40% reduction in agent handling time and a 22-point CSAT uplift within 6 months for airline clients of similar size to SmartWings. I''d like to show you how we''d get there for you. Can I start by asking: what''s your single biggest pain point in passenger communications today?"}, {"role": "buyer", "content": "Missing luggage and claims are a nightmare \u2014 it clogs the call centre and passengers are furious when responses take days. But I''ve heard this 40% figure from other AI vendors too. What makes yours different, and how would it actually work with our Sabre PSS?"}, {"role": "seller", "content": "Great \u2014 missing luggage is exactly where we''ve seen the fastest ROI. Our AI handles the full claims intake, status updates, and escalation. Passengers get real-time SMS and app updates; only genuinely complex cases reach your agents. On Sabre \u2014 we have a pre-built connector for Sabre SynXis and PSS modules. We deploy through a middleware layer, which means we never touch flight ops systems directly. We run a 4-week parallel pilot first, so if anything looks wrong we catch it before it affects live operations. Would it help to walk through the technical architecture?"}, {"role": "buyer", "content": "A middleware layer sounds sensible, but I need specifics. Have you actually done a Sabre integration before, or are you selling us a first attempt? And what failsafe do you have if the AI makes a mistake on a claim \u2014 say it approves a fraudulent one?"}, {"role": "seller", "content": "We''ve delivered three integrations with Sabre PSS \u2014 I can share reference contacts from two airline customers post-call if that''s useful. On fraud: our system runs a two-tier check. Tier 1 is automated AI triage. Any claim flagged as anomalous or above a configurable currency threshold immediately routes to a human agent \u2014 your team retains full approval control for high-risk cases. Tier 2 is an audit trail: every AI decision is logged with confidence scores so your compliance team can review. You''re not handing a blank cheque to the AI \u2014 your agents stay in the loop where it matters."}, {"role": "buyer", "content": "That''s actually a solid answer. But my CFO will ask about ROI within 12 months. How do I build that business case? And honestly \u2014 we have union agreements that limit how much we can automate. Will this work without shrinking our call centre headcount?"}, {"role": "seller", "content": "The union constraint is one we see often and our model fits well here. The AI takes over the repetitive, high-volume tier-0 contacts \u2014 status checks, simple rebooking, lost luggage registration. Your agents stay on the floor but handle escalations and complex empathy-heavy cases. In practice, productivity per agent goes up, headcount stays flat, and you handle volume growth without hiring. For the CFO: if your call centre handles 2 million passenger contacts yearly and we deflect 35-40% of them, that''s 700,000+ fewer agent-handled cases. At a conservative $4 cost-per-contact, that''s $2.8M in savings against a typical implementation cost of under $600K. ROI inside 12 months is very achievable, and I can build a customised financial model with your actual numbers."}, {"role": "buyer", "content": "Those numbers are compelling if they hold up. But I need to know about data security. Our passengers give us passport numbers, payment info, medical flags for special assistance requests. How does Ciklum handle all of that? And is any of this data used to train AI models?"}, {"role": "seller", "content": "All data stays within a dedicated tenant environment \u2014 we don''t use a shared model. Your passenger data is encrypted and we are fully GDPR compliant. We don''t use your data to train base models \u2014 it stays yours. I can send you our security documentation if you''d like to review the details."}, {"role": "buyer", "content": "That''s fine as far as it goes, but I need more detail \u2014 certifications, exactly where the data is hosted, what happens if there''s a breach. This needs to go through our CISO. Where are we on next steps?"}, {"role": "seller", "content": "Absolutely \u2014 I''ll send you our full security dossier including SOC 2 Type II report and our data residency options, which include EU-hosted deployment on AWS Frankfurt. For next steps: I''d suggest a technical deep-dive call with your IT and CISO team in the next two weeks, and I''ll prepare the customised ROI model for your CFO in parallel. Does that work for you?"}, {"role": "buyer", "content": "Yes, that works. I''ll involve the CISO and IT lead. Send the model and the security pack by end of week."}]','2026-03-07 15:46:43.808069');
CREATE TABLE "sparring_profiles" (
                        project_id VARCHAR PRIMARY KEY,
                        current_level VARCHAR,
                        priority_weaknesses_json TEXT,
                        sessions_count INTEGER,
                        updated_at DATETIME
                    );
INSERT INTO "sparring_profiles" VALUES('demo-smartwings-123','intermediate','["Limited direct response to buyer''s specific pain points", "Insufficient handling of objections", "Could have provided more concrete proof points"]',5,'2026-03-10 07:41:47.169546');
CREATE TABLE "project_documents" (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        project_id VARCHAR NOT NULL,
                        filename VARCHAR NOT NULL,
                        file_type VARCHAR,
                        file_size INTEGER,
                        qdrant_doc_id VARCHAR,
                        created_at DATETIME,
                        FOREIGN KEY(project_id) REFERENCES scenarios(scenario_id)
                    );
CREATE INDEX ix_project_documents_project_id ON project_documents(project_id);
CREATE INDEX ix_sessions_project_id ON sessions(project_id);
CREATE INDEX ix_sessions_scenario_id ON sessions(scenario_id);
CREATE INDEX ix_session_scores_project_id ON session_scores(project_id);
CREATE INDEX ix_session_scores_session_id ON session_scores(session_id);
CREATE UNIQUE INDEX ux_sparring_profiles_project_id
                ON sparring_profiles(project_id)
                ;
